// Legacy callers keep their original acceptance semantics. Public recommendation surfaces use the strict getter below.
export function getAcceptedPixelArtCases(cases = PIXEL_ART_CASES) {
  return cases.filter((item) => item.acceptance === 'accepted');
}
export function getUserAcceptedPixelArtCases(cases = PIXEL_ART_CASES) {
  return cases.filter((item) => item.userAcceptance === 'accepted' && item.studyStatus === 'reviewed');
}
export function getComparisonPixelArtCases(cases = PIXEL_ART_CASES) {
  return cases.filter((item) => item.userAcceptance === 'pending' && item.studyStatus === 'reviewed' && item.internalDecision && item.beforePng && item.afterPng);
}
export function getVisiblePixelArtCases(cases = PIXEL_ART_CASES) {
  return [...getUserAcceptedPixelArtCases(cases), ...getComparisonPixelArtCases(cases)];
}
export function getPendingPixelArtCases(cases = PIXEL_ART_CASES) {
  return cases.filter((item) => item.userAcceptance === 'pending');
}
